<?php require_once __DIR__.'/auth.php'; require_admin(); $pdo=db(); if(isset($_GET['status'],$_GET['id'])){$pdo->prepare('UPDATE enquiries SET status=? WHERE id=?')->execute([$_GET['status'],(int)$_GET['id']]);header('Location: enquiries.php');exit;} $items=$pdo->query('SELECT * FROM enquiries ORDER BY created_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enquiries</title><style>body{font-family:Arial;background:#f5f1ea;padding:25px}.wrap{max-width:1100px;margin:auto}.item{background:#fff;padding:20px;border-radius:8px;margin:15px 0}.btn{background:#7d402d;color:#fff;padding:7px 10px;text-decoration:none;border-radius:4px;margin-right:5px}.new{border-left:5px solid #b85}</style></head><body><div class="wrap"><a href="index.php">← Dashboard</a><h1>Project Enquiries</h1><?php foreach($items as $x):?><div class="item <?php echo $x['status']==='new'?'new':'';?>"><h3><?php echo htmlspecialchars($x['name']);?> — <?php echo htmlspecialchars($x['service']);?></h3><p><b>Email:</b> <?php echo htmlspecialchars($x['email']);?> &nbsp; <b>Phone:</b> <?php echo htmlspecialchars($x['phone']??'');?></p><p><?php echo nl2br(htmlspecialchars($x['message']));?></p><small><?php echo $x['created_at'];?> · Status: <?php echo htmlspecialchars($x['status']);?></small><p><a class="btn" href="?id=<?php echo $x['id'];?>&status=read">Mark read</a><a class="btn" href="?id=<?php echo $x['id'];?>&status=replied">Replied</a><a class="btn" href="?id=<?php echo $x['id'];?>&status=closed">Close</a></p></div><?php endforeach;?></div></body></html>
